"""Verificação de UI via CDP do Chrome headless (sem baixar navegador).

Abre a tela de sequências, espera o Angular renderizar o catálogo, clica numa
sequência, confere os resultados e cadastra uma nova pelo formulário.
"""

import json
import subprocess
import sys
import time
import urllib.request

import websocket

CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
URL = sys.argv[1] if len(sys.argv) > 1 else "http://127.0.0.1:5055/#/porsequencia"
PORTA_CDP = 9222


def abrir_chrome():
    proc = subprocess.Popen(
        [CHROME, "--headless=new", "--disable-gpu", "--no-sandbox",
         "--remote-debugging-port=%d" % PORTA_CDP,
         "--window-size=1440,900", "about:blank"],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    for _ in range(60):
        try:
            with urllib.request.urlopen("http://127.0.0.1:%d/json" % PORTA_CDP) as r:
                paginas = json.loads(r.read().decode())
            for p in paginas:
                if p.get("type") == "page":
                    return proc, p["webSocketDebuggerUrl"]
        except Exception:
            pass
        time.sleep(0.25)
    proc.kill()
    raise SystemExit("chrome headless não subiu")


def sessao(ws_url):
    ws = websocket.create_connection(ws_url, timeout=30)
    seq = [0]

    def enviar(method, **params):
        seq[0] += 1
        ws.send(json.dumps({"id": seq[0], "method": method, "params": params}))
        while True:
            msg = json.loads(ws.recv())
            if msg.get("id") == seq[0]:
                if "error" in msg:
                    raise RuntimeError(msg["error"])
                return msg.get("result", {})

    return ws, enviar


DOM = r"""
(async () => {
  const esperar = async (fn, ms = 15000) => {
    const fim = Date.now() + ms;
    while (Date.now() < fim) {
      if (fn()) return true;
      await new Promise(r => setTimeout(r, 150));
    }
    return false;
  };
  const itens = () => Array.from(document.querySelectorAll('.sequencia-item'));
  const nomes = () => itens().map(i => i.querySelector('.sequencia-nome').textContent.trim());
  const cards = () => Array.from(document.querySelectorAll('.music-card'));

  const catalogoRenderizou = await esperar(() => itens().length > 0);
  const antes = nomes();

  // clique numa sequência do catálogo
  const alvo = itens().find(i => i.querySelector('.sequencia-nome').textContent.includes('Em'));
  alvo.click();
  const resultados = await esperar(() => cards().length > 0);
  const aposClique = {
    titulo: document.querySelector('#results h4').textContent.trim(),
    selecionada: (document.querySelector('.sequencia-selecionada') || {}).textContent || '',
    cards: cards().length,
    primeira: cards().length ? cards()[0].querySelector('.music-title').textContent.trim() : null
  };

  // cadastro pelo formulário
  const input = document.querySelector('.sequencia-form input');
  input.value = 'F G Am';
  input.dispatchEvent(new Event('input', { bubbles: true }));
  const enviou = await esperar(() => input.value === 'F G Am');
  document.querySelector('.sequencia-form button[type=submit]').click();
  const criou = await esperar(() => nomes().length > antes.length && cards().length > 0);
  const depois = nomes();
  const estadoFinal = {
    inputReferenciaOk: enviou,
    totalAntes: antes.length,
    totalDepois: depois.length,
    nova: depois.find(n => n === 'F - G - Am') || null,
    erroVisivel: (document.querySelector('.sequencia-erro') || {}).textContent || '',
    selecionada: (document.querySelector('.sequencia-selecionada') || {}).textContent || '',
    cards: cards().length
  };

  // duplicata: mesmo cadastro de novo deve mostrar aviso e selecionar a existente
  input.value = 'F G Am';
  input.dispatchEvent(new Event('input', { bubbles: true }));
  await new Promise(r => setTimeout(r, 100));
  document.querySelector('.sequencia-form button[type=submit]').click();
  const avisou = await esperar(() => (document.querySelector('.sequencia-erro') || {}).textContent.trim() !== '');
  const duplicata = {
    aviso: (document.querySelector('.sequencia-erro') || {}).textContent || '',
    total: nomes().length
  };

  return JSON.stringify({ catalogoRenderizou, antes, resultados, aposClique, estadoFinal, avisou,
                          duplicata, cardsAposDuplicata: cards().length }, null, 2);
})()
"""


def main():
    proc, ws_url = abrir_chrome()
    ws, enviar = sessao(ws_url)
    try:
        enviar("Runtime.enable")
        enviar("Log.enable")
        enviar("Page.enable")
        enviar("Page.navigate", url=URL)
        time.sleep(2.5)
        r = enviar("Runtime.evaluate", expression=DOM, awaitPromise=True,
                   returnByValue=True, timeout=40000)
        if "exceptionDetails" in r:
            print("EXCEÇÃO:", json.dumps(r["exceptionDetails"], indent=2, ensure_ascii=False))
        print(r.get("result", {}).get("value"))

        enviar("Runtime.evaluate", expression="void 0")
        logs = []
        ws.settimeout(0.5)
        try:
            while True:
                msg = json.loads(ws.recv())
                if msg.get("method") == "Log.entryAdded":
                    logs.append(msg["params"]["entry"])
                if msg.get("method") == "Runtime.exceptionThrown":
                    logs.append({"level": "exception",
                                 "text": msg["params"]["exceptionDetails"].get("text")})
        except Exception:
            pass
        problemas = [l for l in logs if l.get("level") in ("error", "exception")]
        print("console/erros de rede:", json.dumps(problemas, ensure_ascii=False) if problemas else "nenhum")
    finally:
        ws.close()
        proc.kill()


if __name__ == "__main__":
    main()

